// Inserts text into whatever app has focus with a transactional paste, which works in Terminal and iTerm2
// (terminals have no writable AX selected-text attribute, and synthesised typing drops characters):
// snapshot the pasteboard, write the text marked transient and auto-generated so clipboard managers skip it,
// post Cmd+V, wait for the target to read it, then put the user's clipboard back.
import AppKit
import ApplicationServices
import Carbon.HIToolbox

@MainActor
enum Paster {
    static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")
    /// Terminal and iTerm2 read the pasteboard asynchronously after Cmd+V; 150 ms is comfortably past that.
    static let restoreDelay: Duration = .milliseconds(150)

    enum Outcome { case pasted, copiedOnly, nothing }

    /// Pastes `text`. With `keep`, the text stays on the clipboard afterwards. Without Accessibility access the
    /// text is left on the clipboard for the user to paste themselves.
    static func insert(_ text: String, keep: Bool) async -> Outcome {
        guard !text.isEmpty else { return .nothing }
        let pb = NSPasteboard.general
        guard AXIsProcessTrusted() else {
            pb.clearContents()
            pb.setString(text, forType: .string)
            return .copiedOnly
        }

        let saved = keep ? [] : snapshot(pb)
        pb.clearContents()
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        if !keep {
            item.setData(Data(), forType: transientType)
            item.setData(Data(), forType: autoGeneratedType)
        }
        pb.writeObjects([item])
        let ourChange = pb.changeCount

        await waitForModifiersReleased()
        postCommandV()

        if !keep {
            try? await Task.sleep(for: restoreDelay)
            // If something else wrote to the clipboard meanwhile, leave it alone.
            if pb.changeCount == ourChange { restore(saved, to: pb) }
        }
        return .pasted
    }

    /// Every item and every type on the pasteboard, as raw data.
    static func snapshot(_ pb: NSPasteboard) -> [[(NSPasteboard.PasteboardType, Data)]] {
        (pb.pasteboardItems ?? []).map { item in
            item.types.compactMap { type in item.data(forType: type).map { (type, $0) } }
        }
    }

    static func restore(_ saved: [[(NSPasteboard.PasteboardType, Data)]], to pb: NSPasteboard) {
        pb.clearContents()
        guard !saved.isEmpty else { return }
        let items: [NSPasteboardItem] = saved.map { pairs in
            let item = NSPasteboardItem()
            for (type, data) in pairs { item.setData(data, forType: type) }
            return item
        }
        pb.writeObjects(items)
    }

    /// The user may still be holding Option from the hotkey; let it go first so the target sees a clean Cmd+V.
    static func waitForModifiersReleased() async {
        let held: CGEventFlags = [.maskAlternate, .maskShift, .maskControl, .maskSecondaryFn]
        for _ in 0..<40 {
            if CGEventSource.flagsState(.hidSystemState).intersection(held).isEmpty { return }
            try? await Task.sleep(for: .milliseconds(15))
        }
    }

    static func postCommandV() {
        let source = CGEventSource(stateID: .hidSystemState)
        let v = CGKeyCode(kVK_ANSI_V)
        let down = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: true)
        let up = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: false)
        down?.flags = .maskCommand
        up?.flags = .maskCommand
        down?.post(tap: .cghidEventTap)
        up?.post(tap: .cghidEventTap)
    }
}
